package dev.shadw.khemet.mobs;

import net.minecraft.client.renderer.entity.EntityRendererProvider;
import net.minecraft.client.renderer.entity.MobRenderer;
import net.minecraft.resources.ResourceLocation;

/** Renders the The Forgotten Pharaoh with its own model and texture. Generated by shadw-mod mob. */
public class ForgottenPharaohRenderer extends MobRenderer<ForgottenPharaoh, ForgottenPharaohModel.State, ForgottenPharaohModel> {
	private static final ResourceLocation TEXTURE = ResourceLocation.fromNamespaceAndPath("khemet", "textures/entity/forgotten_pharaoh.png");

	public ForgottenPharaohRenderer(EntityRendererProvider.Context context) {
		super(context, new ForgottenPharaohModel(context.bakeLayer(ForgottenPharaohModel.LAYER)), 0.9F);
	}

	@Override
	public ForgottenPharaohModel.State createRenderState() {
		return new ForgottenPharaohModel.State();
	}

	@Override
	public void extractRenderState(ForgottenPharaoh entity, ForgottenPharaohModel.State state, float partialTick) {
		super.extractRenderState(entity, state, partialTick);
		state.attackTime = entity.getAttackAnim(partialTick);
	}

	@Override
	public ResourceLocation getTextureLocation(ForgottenPharaohModel.State state) {
		return TEXTURE;
	}
}
